function d_raft_vote(P,R){var n=P.nodes||5,votes={};for(var i=0;i<n;i++){var c=Math.floor(R()*n);votes[c]=(votes[c]||0)+1;}var lead=Object.keys(votes).sort(function(a,b){return votes[b]-votes[a];})[0];return{nodes:n,votes:votes,leader:+lead,elected:votes[lead]>n/2};}

